/* GridIQ Botswana UI v1.4.0
 * Evidence rules:
 * - no fabricated operational grid values;
 * - no synthetic hourly demand/solar series;
 * - official snapshots, live APIs, historical references and external benchmarks are visibly separated.
 */
'use strict';

const GRID_VERSION='1.4.0';
const STORAGE_KEY='gridiq-botswana-ui-v1.4';
window.__GRID_BOOTED=false;
const FIXTURE_MODE=new URLSearchParams(location.search).has('fixture');

const $=s=>document.querySelector(s);
const $$=s=>Array.from(document.querySelectorAll(s));
const esc=s=>String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
const fmt=(n,d=0)=>Number(n).toLocaleString(undefined,{maximumFractionDigits:d,minimumFractionDigits:d});
const compact=n=>Intl.NumberFormat(undefined,{notation:'compact',maximumFractionDigits:1}).format(Number(n));
const pct=n=>`${fmt(n,1)}%`;

function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.hidden=false;clearTimeout(toast.t);toast.t=setTimeout(()=>t.hidden=true,4200)}
async function api(path,options={}){const r=await fetch(path,{headers:{'Content-Type':'application/json',...(options.headers||{})},...options});if(!r.ok){let d={};try{d=await r.json()}catch{};throw new Error(d.detail||`HTTP ${r.status}`)}return r.json()}

function loadStyleOnce(id,href){if(document.getElementById(id))return;const l=document.createElement('link');l.id=id;l.rel='stylesheet';l.href=href;document.head.appendChild(l)}
function loadScriptOnce(id,src,globalName,timeoutMs=15000){if(globalName&&window[globalName])return Promise.resolve(true);const existing=document.getElementById(id);if(existing?.dataset.loaded==='1')return Promise.resolve(true);return new Promise((resolve,reject)=>{const s=existing||document.createElement('script');if(!existing){s.id=id;s.src=src;s.async=true;s.crossOrigin='anonymous';document.head.appendChild(s)}const timer=setTimeout(()=>reject(new Error(`Timed out loading ${src}`)),timeoutMs);s.onload=()=>{clearTimeout(timer);s.dataset.loaded='1';resolve(true)};s.onerror=()=>{clearTimeout(timer);reject(new Error(`Failed to load ${src}`))}})}
async function ensureVendors(){if(FIXTURE_MODE){setVendorPill(false);return false}const jobs=[];if(!window.L){loadStyleOnce('leaflet-css','https://unpkg.com/leaflet@1.9.4/dist/leaflet.css');jobs.push(loadScriptOnce('leaflet-js','https://unpkg.com/leaflet@1.9.4/dist/leaflet.js','L'))}if(!window.Chart)jobs.push(loadScriptOnce('chart-js','https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js','Chart'));if(!jobs.length){setVendorPill(true);return true}const r=await Promise.allSettled(jobs);const ok=r.every(x=>x.status==='fulfilled');setVendorPill(ok);return ok}
function setVendorPill(ok){const p=$('#vendorPill');if(!p)return;p.textContent=ok?'Visual libs ready':'Visual libs degraded';p.className=`pill ${ok?'ok':'bad'}`}

const charts=new Map();
const colors={cyan:'#42d6e7',green:'#5de39b',amber:'#f4b85c',red:'#ff6f79',blue:'#5fa9ff',violet:'#9b89ff',grid:'rgba(120,150,170,.12)',text:'#8296a8'};
function chartBase(){return{responsive:true,maintainAspectRatio:false,animation:{duration:250},interaction:{mode:'index',intersect:false},plugins:{legend:{labels:{color:colors.text,boxWidth:9,boxHeight:9,font:{size:10}}},tooltip:{backgroundColor:'#0c1722',borderColor:'#2a4052',borderWidth:1,titleColor:'#e8f0f7',bodyColor:'#c4d1dc'}},scales:{x:{ticks:{color:colors.text,font:{size:9},autoSkip:true,maxTicksLimit:12,maxRotation:0},grid:{display:false}},y:{ticks:{color:colors.text,font:{size:9}},grid:{color:colors.grid},beginAtZero:true}}}}
function mountChart(id,config){const el=document.getElementById(id);if(!el||!window.Chart)return false;if(charts.has(id)){try{charts.get(id).destroy()}catch{}charts.delete(id)}charts.set(id,new Chart(el,config));return true}
function lineChart(id,labels,series,opts={}){const o=chartBase();if(opts.beginAtZero===false)o.scales.y.beginAtZero=false;return mountChart(id,{type:'line',data:{labels,datasets:series.map((s,i)=>({label:s.label,data:s.data,borderColor:s.color||[colors.cyan,colors.green,colors.amber,colors.violet][i%4],backgroundColor:(s.color||colors.cyan)+'20',fill:!!s.fill,tension:.28,borderWidth:2,pointRadius:opts.points?2:0,spanGaps:true}))},options:o})}
function barChart(id,labels,series,opts={}){const o=chartBase();if(opts.horizontal){o.indexAxis='y';o.scales.x={ticks:{color:colors.text,font:{size:9}},grid:{color:colors.grid},beginAtZero:true};o.scales.y={ticks:{color:colors.text,font:{size:9}},grid:{display:false}}}return mountChart(id,{type:'bar',data:{labels,datasets:series.map((s,i)=>({label:s.label,data:s.data,backgroundColor:s.color||[colors.cyan,colors.green,colors.amber,colors.violet][i%4],borderRadius:5,borderSkipped:false}))},options:o})}
function doughnutChart(id,labels,data){return mountChart(id,{type:'doughnut',data:{labels,datasets:[{data,backgroundColor:[colors.amber,colors.green,colors.violet,colors.cyan,colors.red],borderColor:'#0c1722',borderWidth:4}]},options:{responsive:true,maintainAspectRatio:false,cutout:'70%',plugins:{legend:{position:'right',labels:{color:colors.text,boxWidth:9,font:{size:10}}},tooltip:{backgroundColor:'#0c1722',borderColor:'#2a4052',borderWidth:1}}}})}

/* Map lifecycle. The map is recreated whenever #energyMap is recreated by page navigation. */
let map=null,layers={},mapContainer=null,selectionCb=()=>{},lastGeoJSON=null;
function resetDetachedMap(){if(!map)return;const current=document.getElementById('energyMap');if(!mapContainer||!mapContainer.isConnected||mapContainer!==current){try{map.remove()}catch{}map=null;layers={};mapContainer=null}}
function showMapFallback(msg){const el=$('#energyMap');if(el)el.innerHTML=`<div class="map-fallback"><b>Map unavailable</b><span>${esc(msg)}</span></div>`}
function ensureMap(){resetDetachedMap();if(!window.L){showMapFallback('Leaflet has not loaded. Internet access is required for the OpenStreetMap basemap library.');return null}if(map)return map;const target=$('#energyMap');if(!target)return null;target.innerHTML='';mapContainer=target;map=L.map(target,{zoomControl:true,preferCanvas:true,minZoom:5,maxZoom:16}).setView([-22.2,24.7],6);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(map);layers.lines=L.layerGroup().addTo(map);layers.assets=L.layerGroup().addTo(map);layers.topology=L.layerGroup().addTo(map);layers.benchmark=L.layerGroup();map.on('click',e=>selectionCb({type:'location',lat:e.latlng.lat,lng:e.latlng.lng,name:'Selected analysis point'}));setTimeout(()=>map.invalidateSize(),70);return map}
function voltageColor(raw=''){const vals=String(raw||'').replace(/,/g,';').split(';').map(x=>Number(x.trim())).filter(Number.isFinite);const v=vals.length?Math.max(...vals):0;if(v>=350000)return '#ff7c68';if(v>=180000)return '#f4b85c';if(v>=110000)return '#42d6e7';if(v>=50000)return '#5fa9ff';return '#657f94'}
function assetIcon(p){const c=p.power==='substation'?colors.cyan:(p.power==='plant'||p.power==='generator'?colors.green:colors.violet);return L.divIcon({className:'',html:`<div style="width:13px;height:13px;border-radius:50%;background:${c};border:3px solid #071019;box-shadow:0 0 0 1px ${c},0 0 12px ${c}66"></div>`,iconSize:[13,13],iconAnchor:[6,6]})}
function topologyMarkers(fc){const g=new Map();for(const f of fc.features||[]){if(f.geometry?.type!=='LineString')continue;const c=f.geometry.coordinates||[];for(let i=0;i<c.length;i++){const [lon,lat]=c[i];const k=`${lon.toFixed(5)},${lat.toFixed(5)}`;if(!g.has(k))g.set(k,{lon,lat,n:new Set()});if(i>0){const [plon,plat]=c[i-1],pk=`${plon.toFixed(5)},${plat.toFixed(5)}`;g.get(k).n.add(pk)}if(i<c.length-1){const [nlon,nlat]=c[i+1],nk=`${nlon.toFixed(5)},${nlat.toFixed(5)}`;g.get(k).n.add(nk)}}}return Array.from(g.values()).filter(x=>x.n.size===1||x.n.size>=3)}
function renderPowerData(result,{fit=true}={}){const m=ensureMap();if(!m)return;lastGeoJSON=result?.data||result;if(!lastGeoJSON)return;layers.lines.clearLayers();layers.assets.clearLayers();layers.topology.clearLayers();for(const f of lastGeoJSON.features||[]){const p=f.properties||{};let layer;if(f.geometry?.type==='LineString'){layer=L.geoJSON(f,{style:{color:voltageColor(p.voltage),weight:2.4,opacity:.82}});layers.lines.addLayer(layer)}else if(f.geometry?.type==='Point'){const [lon,lat]=f.geometry.coordinates;layer=L.marker([lat,lon],{icon:assetIcon(p)});layers.assets.addLayer(layer)}else{layer=L.geoJSON(f,{style:{color:colors.cyan,weight:1,fillOpacity:.10}});layers.assets.addLayer(layer)}layer.bindTooltip(`${p.name||p.power||'Power asset'}${p.voltage?` · ${p.voltage} V`:''}`,{className:'asset-tip'});layer.on('click',()=>selectionCb({type:'osm',feature_id:f.id,...p,geometry:f.geometry}))}for(const n of topologyMarkers(lastGeoJSON)){const degree=n.n.size;const c=degree>=3?colors.red:colors.blue;L.circleMarker([n.lat,n.lon],{radius:degree>=3?4.5:3,color:c,weight:1.5,fillColor:c,fillOpacity:.9}).bindTooltip(degree>=3?`OSM geometry junction · degree ${degree}`:'OSM geometry endpoint').addTo(layers.topology)}if(fit){try{const group=L.featureGroup([layers.lines,layers.assets]);const b=group.getBounds();if(b.isValid())m.fitBounds(b.pad(.04))}catch{}}}
function setMapLayer(name,visible){const m=ensureMap();if(!m||!layers[name])return;if(visible&&!m.hasLayer(layers[name]))layers[name].addTo(m);if(!visible&&m.hasLayer(layers[name]))m.removeLayer(layers[name])}
function utilColor(v){if(v==null)return '#657f94';if(v>=100)return colors.red;if(v>=80)return colors.amber;if(v>=50)return colors.cyan;return colors.green}
function renderBenchmarkFlows(result){const m=ensureMap();if(!m||!layers.benchmark||!lastGeoJSON)return;layers.benchmark.clearLayers();if(!result?.supported)return;const byId=new Map((result.flows||[]).map(x=>[x.feature_id,x]));for(const f of lastGeoJSON.features||[]){const r=byId.get(f.id);if(!r||f.geometry?.type!=='LineString')continue;L.geoJSON(f,{style:{color:utilColor(r.utilization_pct),weight:5,opacity:.78,dashArray:'8 5'}}).bindTooltip(`Benchmark transfer: ${fmt(r.abs_flow_mw,1)} MW · ${fmt(r.utilization_pct,1)}% of benchmark secure rating`,{className:'asset-tip'}).addTo(layers.benchmark)}layers.benchmark.addTo(m)}

const NAV=[['overview','Overview'],['network','Network & Topology'],['generation','Generation'],['storage','Storage'],['demand','Demand'],['scenarios','Scenario Lab'],['data','Data Evidence'],['audit','Audit']];
const defaults={view:'overview',catalog:[],baseline:null,benchmarks:null,electricalBenchmarks:null,auditReport:null,evidenceManifest:null,plants:null,neus:null,censusDistricts:null,districtContext:null,osm:{status:'not loaded',payload:null},nasa:null,worldpop:null,selected:null,scenario:null,engineering:{case:'reference',voltage_kv:220,transfer_mw:100,source_lat:-22.522316,source_lon:27.049053,sink_lat:-24.6282,sink_lon:25.9231,result:null,enriched:null},scenarioInputs:{solar_build_mw:0,storage_mw:100,storage_mwh:400,peak_demand_mw:610,operating_capacity_mw:459,reserve_requirement_mw:88,roundtrip_efficiency:0.85,storage_cost_usd_per_kwh:192},topologyVisible:true,benchmarkVisible:true};
const state=structuredClone(defaults);

function restoreState(){try{const p=JSON.parse(localStorage.getItem(STORAGE_KEY)||'{}');if(p.view)state.view=p.view;if(p.nasa)state.nasa=p.nasa;if(p.worldpop)state.worldpop=p.worldpop;if(p.selected)state.selected=p.selected;if(p.scenario)state.scenario=p.scenario;if(p.scenarioInputs)state.scenarioInputs={...state.scenarioInputs,...p.scenarioInputs};if(p.engineering)state.engineering={...state.engineering,...p.engineering,result:null,enriched:null};if(typeof p.topologyVisible==='boolean')state.topologyVisible=p.topologyVisible;if(typeof p.benchmarkVisible==='boolean')state.benchmarkVisible=p.benchmarkVisible}catch(e){console.warn('State restore failed',e)}}
function persistState(){try{const selected=state.selected?.type==='location'?state.selected:(state.selected?.type==='osm'?{type:'osm',feature_id:state.selected.feature_id,name:state.selected.name,power:state.selected.power,voltage:state.selected.voltage,operator:state.selected.operator}:null);const eng={case:state.engineering.case,voltage_kv:state.engineering.voltage_kv,transfer_mw:state.engineering.transfer_mw,source_lat:state.engineering.source_lat,source_lon:state.engineering.source_lon,sink_lat:state.engineering.sink_lat,sink_lon:state.engineering.sink_lon};localStorage.setItem(STORAGE_KEY,JSON.stringify({view:state.view,nasa:state.nasa,worldpop:state.worldpop,selected,scenario:state.scenario,scenarioInputs:state.scenarioInputs,engineering:eng,topologyVisible:state.topologyVisible,benchmarkVisible:state.benchmarkVisible}))}catch(e){console.warn('State persistence failed',e)}}

function panel(title,body,sub=''){return `<section class="panel"><div class="panel-head"><div><h2>${esc(title)}</h2>${sub?`<span>${esc(sub)}</span>`:''}</div></div><div class="panel-body">${body}</div></section>`}
function metric(label,value,unit='',note='',tone=''){return `<section class="panel metric ${tone}"><label>${esc(label)}</label><div class="value">${esc(value)}<span class="unit">${esc(unit)}</span></div><div class="note">${note}</div></section>`}
function chart(id,cls=''){return `<div class="chart-box ${cls}"><canvas id="${id}"></canvas><div class="chart-wait" data-chart-wait="${id}">Chart engine loading…</div></div>`}
function sourceTag(label,type='official'){return `<span class="source-tag ${type}">${esc(label)}</span>`}
function evidenceStrip(){return `<div class="evidence-strip">${sourceTag('OFFICIAL BUNDLED','official')}${sourceTag('LIVE API','live')}${sourceTag('EXTERNAL BENCHMARK','benchmark')}${sourceTag('UNKNOWN ≠ ZERO','unknown')}</div>`}
function callout(title,text,type='warn'){return `<div class="callout ${type}"><b>${esc(title)}</b><p>${text}</p></div>`}
function sourceLink(url,label='Open source'){return url?`<a class="source-link" href="${esc(url)}" target="_blank" rel="noopener">${esc(label)} ↗</a>`:''}

function baseline(){return state.baseline||defaults.baseline}
function q1(){return baseline()?.q1_2026||{generation_mix_pct:{coal:0,diesel:0,solar:0}}}
function sapp(){return baseline()?.sapp_capacity||{installed_capacity_mw:0,operating_capacity_mw:0,current_peak_demand_mw:0,peak_plus_reserves_mw:0,capacity_shortfall_including_reserves_mw:0}}
function gridBase(){return baseline()?.grid||{transmission_km_by_voltage:{}}}
function compactBase(){return baseline()?.energy_compact||{}}

function mapPanel({network=false}={}){return `<section class="panel"><div class="panel-head"><div><h2>${network?'GRID GEOGRAPHY + TOPOLOGY':'BOTSWANA ENERGY NETWORK'}</h2><span>OpenStreetMap basemap + live mapped power infrastructure</span></div><span id="mapSourceState">${esc(state.osm.status)}</span></div><div class="map-wrap ${network?'compact':''}"><div id="energyMap" class="map"></div><div class="map-tools"><button class="map-chip active" data-layer="lines">Lines</button><button class="map-chip active" data-layer="assets">Assets</button><button class="map-chip ${state.topologyVisible?'active':''}" data-layer="topology">Topology nodes</button><button class="map-chip ${state.engineering.result?.supported&&state.benchmarkVisible?'active':''}" data-layer="benchmark">Benchmark flow</button><button class="map-chip" id="refreshOsm">Refresh OSM</button></div><div class="map-legend"><span><i class="legend-line" style="background:#ff7c68"></i>400 kV class tag</span><span><i class="legend-line" style="background:#f4b85c"></i>220 kV</span><span><i class="legend-line" style="background:#42d6e7"></i>132 kV</span><span><b>Red dots</b> geometry junctions · <b>Blue</b> endpoints</span><span><b>Dashed overlay</b> benchmark transfer only</span></div></div></section>`}

function overview(){const b=baseline(),x=q1(),s=sapp(),c=compactBase();if(!b)return loadingView('Loading verified Botswana baseline…');return `<div class="workspace">${evidenceStrip()}<div class="grid overview-grid"><div class="left-col">${panel('EVIDENCE STATUS',`<div class="card-stack"><div class="asset-card"><div class="row"><div class="glyph">Σ</div><div><b>Stats Botswana Q1 2026</b><small>Generation · imports · distribution</small></div><div class="status-dot"></div></div></div><div class="asset-card"><div class="row"><div class="glyph">↔</div><div><b>SAPP system snapshot</b><small>Capacity · peak demand</small></div><div class="status-dot"></div></div></div><div class="asset-card"><div class="row"><div class="glyph">⌁</div><div><b>OSM power network</b><small>Live public geometry</small></div><div class="status-dot"></div></div></div></div>`)}${panel('CURRENT SYSTEM GAP',`<div class="big-number">${fmt(Math.max(0,s.current_peak_demand_mw-s.operating_capacity_mw))}<small> MW</small></div><p class="muted">Operating capacity below current SAPP peak-demand snapshot. With reserve requirement, SAPP reports a <b>${fmt(Math.abs(s.capacity_shortfall_including_reserves_mw))} MW</b> shortfall.</p><button class="btn" data-go="demand">Inspect demand →</button>`)}</div>${mapPanel()}<div class="right-col">${panel('Q1 2026 SYSTEM SNAPSHOT',`<div class="fact-list"><div><span>Local generation</span><b>${fmt(x.local_generation_mwh/1000,1)} GWh</b></div><div><span>Imports</span><b>${fmt(x.imports_mwh/1000,1)} GWh</b></div><div><span>Local share of distribution</span><b>${pct(x.local_generation_share_of_distribution_pct)}</b></div><div><span>Coal share of generation</span><b>${pct(x.generation_mix_pct.coal)}</b></div><div><span>Solar share of generation</span><b>${pct(x.generation_mix_pct.solar)}</b></div></div><div class="source-foot">Statistics Botswana · Q1 2026</div>`)}${panel('TRANSITION CONTEXT',`<div class="fact-list"><div><span>Electricity access</span><b>${pct(c.electricity_access_pct_march_2025)}</b></div><div><span>Renewable installed share</span><b>${pct(c.renewable_installed_share_pct_july_2025)}</b></div><div><span>2030 domestic RE target</span><b>${pct(c.renewable_target_pct_2030_domestic_case)}</b></div><div><span>System losses</span><b>${pct(gridBase().system_losses_pct_of_dispatched)}</b></div></div><div class="source-foot">Botswana National Energy Compact</div>`)}</div></div><div class="grid bottom-grid">${metric('Operating capacity',fmt(s.operating_capacity_mw),'MW','SAPP current snapshot')}${metric('Peak demand',fmt(s.current_peak_demand_mw),'MW','SAPP current snapshot')}${metric('Installed capacity',fmt(s.installed_capacity_mw),'MW','SAPP current snapshot')}${metric('2022 population',fmt(b.census.population_2022),'','Statistics Botswana census')}</div><div class="split dashboard-split">${panel('GENERATION vs IMPORTS',chart('overviewTrend','tall'),'Quarterly official series · 2016 Q1–2026 Q1')}${panel('Q1 2026 GENERATION MIX',chart('overviewMix','tall'),'Statistics Botswana')}</div></div>`}

function network(){const g=gridBase(),km=g.transmission_km_by_voltage||{};return `<div class="workspace">${evidenceStrip()}<div class="grid network-head">${metric('400 kV network',fmt(km['400_kv']||0,0),'km','Energy Compact · BPC network ≥132 kV')}${metric('220 kV network',fmt(km['220_kv']||0,1),'km','Energy Compact')}${metric('132 kV network',fmt(km['132_kv']||0,1),'km','Energy Compact')}${metric('System losses',fmt(g.system_losses_pct_of_dispatched||0,2),'%','Transmission + distribution dispatched energy')}</div><div class="split network-split">${mapPanel({network:true})}${panel('OSM-DERIVED TOPOLOGY',`<div id="topologyStats" class="topology-stats">${state.osm.payload?topologyStatsHtml(state.osm.payload):'<div class="loading-inline">Load OSM to calculate geometry topology.</div>'}</div>${callout('Topology boundary','Mapped geometry is observed public evidence. Benchmark engineering mode can add standard R/X/current assumptions, but these remain <b>benchmarks</b>, not BPC asset measurements.','warn')}`,'Observed geometry + explicit benchmark layer')}</div><div class="split dashboard-split">${panel('ENGINEERING BENCHMARK MODE',engineeringControls(),'OSM geometry + PyPSA standard types + user transfer')}${panel('BENCHMARK TRANSFER RESULT',state.engineering.result?engineeringResultHtml(state.engineering.result):`<div class="empty">Load OSM, choose a voltage/case and run a transfer sensitivity. This does not represent current BPC loading.</div>`,'Single-voltage DC sensitivity')}</div><div class="split dashboard-split">${panel('OFFICIAL TRANSMISSION LENGTH',chart('voltageKm','tall'),'Botswana National Energy Compact')}${panel('OPERATIONAL INTERCONNECTORS',`<div class="route-list">${(g.operational_interconnectors||[]).map(x=>`<div class="route"><span>↔</span><b>${esc(x)}</b></div>`).join('')}</div>${callout('Why this matters','Published interconnectors anchor regional supply context. Transfer limits and actual dispatch constraints remain unknown.','good')}`)}</div>${panel('NAMED GRID REINFORCEMENT PIPELINE',`<div class="project-grid">${(g.planned_named_projects||[]).map(x=>`<div class="project-card"><span>PLANNED / PIPELINE</span><b>${esc(x)}</b></div>`).join('')}</div>`,'Energy Compact · planning context')}</div>`}
function topologyStatsHtml(payload){const e=payload?.meta?.evidence_summary||{};const t=e.topology||{};const by=e.mapped_line_length_by_voltage_km||{};return `<div class="stat-grid"><div><small>Line features</small><b>${fmt(e.line_features||0)}</b></div><div><small>Mapped line length</small><b>${fmt(e.mapped_line_length_km||0,1)} km</b></div><div><small>Geometry nodes</small><b>${fmt(t.geometry_nodes||0)}</b></div><div><small>Segments</small><b>${fmt(t.geometry_segments||0)}</b></div><div><small>Components</small><b>${fmt(t.connected_components||0)}</b></div><div><small>Junctions ≥3</small><b>${fmt(t.junctions_degree_3_plus||0)}</b></div></div><div class="mini-table">${Object.entries(by).map(([k,v])=>`<div><span>${esc(k)}</span><b>${fmt(v,1)} km mapped</b></div>`).join('')}</div>`}


function engineeringControls(){const e=state.engineering;return `<div class="controls engineering-controls"><div class="field-grid"><label>Voltage class<select id="eng_voltage"><option value="132" ${e.voltage_kv===132?'selected':''}>132 kV</option><option value="220" ${e.voltage_kv===220?'selected':''}>220 kV</option><option value="400" ${e.voltage_kv===400?'selected':''}>400 kV</option></select></label><label>Benchmark case<select id="eng_case"><option value="conservative" ${e.case==='conservative'?'selected':''}>Conservative</option><option value="reference" ${e.case==='reference'?'selected':''}>Reference</option><option value="high_capacity" ${e.case==='high_capacity'?'selected':''}>High capacity</option></select></label></div>${rangeControl('eng_transfer','User transfer','MW',10,1000,10,e.transfer_mw,'Scenario injection, not observed BPC power flow.')}<div class="field-grid coords"><label>Source lat<input id="eng_source_lat" type="number" step="0.0001" value="${e.source_lat}"></label><label>Source lon<input id="eng_source_lon" type="number" step="0.0001" value="${e.source_lon}"></label><label>Sink lat<input id="eng_sink_lat" type="number" step="0.0001" value="${e.sink_lat}"></label><label>Sink lon<input id="eng_sink_lon" type="number" step="0.0001" value="${e.sink_lon}"></label></div><div class="button-row"><button class="btn" id="useSelectedSink">Use selected map point as sink</button><button class="btn primary" id="runEngineering">Run benchmark transfer</button></div>${callout('Evidence boundary','Line geometry/voltage are OSM evidence. R/X/current/security factor come from PyPSA/PyPSA-Earth benchmark libraries. Unmapped circuits default to one <b>only inside benchmark mode</b> and are flagged.','warn')}</div>`}
function engineeringResultHtml(r){if(!r.supported)return callout('Transfer study blocked',esc(r.reason||'Unsupported network configuration.'),'warn')+`<div class="source-foot">GridIQ refused to bridge disconnected OSM components.</div>`;const s=r.summary,m=r.mapping;return `<div class="screen-result"><div><span>Max benchmark utilisation</span><b>${fmt(s.max_benchmark_utilization_pct,1)}%</b></div><div><span>≥100% benchmark branches</span><b>${fmt(s.branches_at_or_above_100_pct)}</b></div><div><span>Approx. I²R loss</span><b>${fmt(s.approx_total_i2r_loss_mw,2)} MW</b></div><div><span>Mapped component</span><b>${fmt(m.component_nodes)} nodes / ${fmt(m.component_branches)} branches</b></div></div><div class="mini-table top-flow-table">${(r.top_flows||[]).slice(0,8).map(x=>`<div><span>${esc(x.name)} · ${fmt(x.length_km,1)} km</span><b style="color:${utilColor(x.utilization_pct)}">${fmt(x.utilization_pct,1)}% · ${fmt(x.abs_flow_mw,1)} MW</b></div>`).join('')}</div>${callout('Model meaning',esc(r.meta.not)+' '+esc(r.meta.warning),'warn')}`}

function generation(){const x=q1(),b=baseline();const selected=state.selected?.type==='location'?state.selected:null;return `<div class="workspace"><div class="grid bottom-grid">${metric('Coal',fmt(x.generation_mix_mwh.coal/1000,1),'GWh',`${pct(x.generation_mix_pct.coal)} of Q1 2026 generation`)}${metric('Solar',fmt(x.generation_mix_mwh.solar/1000,1),'GWh',`${pct(x.generation_mix_pct.solar)} of Q1 2026 generation`)}${metric('Diesel',fmt(x.generation_mix_mwh.diesel/1000,2),'GWh',`${pct(x.generation_mix_pct.diesel)} of Q1 2026 generation`)}${metric('Total',fmt(x.local_generation_mwh/1000,1),'GWh','Statistics Botswana Q1 2026')}</div><div class="split dashboard-split">${panel('GENERATION MIX',chart('generationMix','tall'),'Measured Q1 2026 energy')}${panel('QUARTERLY GENERATION & IMPORTS',chart('generationTrend','tall'),'Measured national energy volumes')}</div><div class="split dashboard-split">${panel('SITE RESOURCE CHECK — NASA POWER',`<div class="resource-point"><small>Analysis coordinate</small><b>${selected?`${selected.lat.toFixed(4)}, ${selected.lng.toFixed(4)}`:'Gaborone default: -24.6500, 25.9100'}</b><p>Click anywhere on the Overview/Network map to set a site, then return here.</p><button id="loadNasa" class="btn primary">Load 14-day NASA POWER window</button></div>${state.nasa?`<div class="source-foot">${esc(state.nasa.meta.source)} · ${esc(state.nasa.meta.start)} to ${esc(state.nasa.meta.end)} · ${esc(state.nasa.meta.cache||'live')}</div>`:''}${chart('nasaChart','tall')}`,'Live planning-grade resource data')}${panel('PUBLIC PLANT REFERENCE',`<div id="plantReference">${(state.plants?.plants||[]).map(p=>`<div class="asset-card"><small>${esc(p.status)} · ${esc(p.fuel)}</small><b>${esc(p.display_name||p.name)} · ${fmt(p.capacity_mw)} MW</b><span>${p.latitude.toFixed(4)}, ${p.longitude.toFixed(4)}</span></div>`).join('')||'<div class="empty">Historical reference unavailable.</div>'}</div>${callout('Reference warning','WRI Global Power Plant Database is historical and no longer actively maintained. Current Statistics Botswana/BPC figures override it.','warn')}`,'Historical geolocation cross-check')}</div><div class="callout good"><b>Verified solar sites in the Q1 2026 brief</b><p>Statistics Botswana explicitly names solar plants in Bobonong, Phakalane, Shakawe and Mmadinare. This release does not invent plant-level output allocations that the report does not provide.</p></div></div>`}

function storage(){const b=state.benchmarks?.utility_scale_bess_2024||{};const sc=state.scenario;return `<div class="workspace"><div class="grid bottom-grid">${metric('Installed-cost benchmark',`$${fmt(b.global_total_installed_cost_usd_per_kwh||0)}`,'/kWh','IRENA 2024 global utility-scale BESS')}${metric('Cost decline',fmt(b.cost_decline_2010_to_2024_pct||0),'%','2010 → 2024 · IRENA')}${metric('Round-trip efficiency',fmt(b.round_trip_efficiency_pct_nrel_atb||0),'%','NREL ATB benchmark')}${metric('4-hour benchmark CF',fmt(b.four_hour_one_cycle_per_day_capacity_factor_pct||0,1),'%','One cycle/day · NREL ATB')}</div><div class="split dashboard-split">${panel('BATTERY COST TREND',chart('storageCost','tall'),'IRENA · 2010 vs 2024')}${panel('BESS SCREENING',storageControls()+(sc?scenarioScreenHtml(sc):'<div class="empty">Set a storage size and run screening. No synthetic hourly dispatch is generated.</div>'),'User scenario + published benchmark')}</div>${panel('WHAT STORAGE CAN / CANNOT PROVE',`<div class="decision-grid"><div class="decision-card good"><span>CAN SCREEN</span><b>Duration, benchmark cost, efficiency-adjusted energy</b><p>These are direct calculations from user-entered MW/MWh plus published IRENA/NREL benchmarks.</p></div><div class="decision-card bad"><span>CANNOT YET PROVE</span><b>Import reduction, congestion relief, reliability capacity credit</b><p>Those need time-aligned load, renewable output and a validated electrical network model.</p></div></div>${callout('Botswana-specific storage gap','No public Botswana BESS telemetry/operating dataset is integrated here. Storage asset state-of-charge is therefore <b>not fabricated</b>.','warn')}`)}</div>`}
function storageControls(){const p=state.scenarioInputs;return `<div class="controls compact-controls"><div class="control"><label>Battery power <b><output id="out_storage_mw">${fmt(p.storage_mw)}</output> MW</b></label><input id="storage_mw" type="range" min="0" max="1000" step="10" value="${p.storage_mw}"></div><div class="control"><label>Battery energy <b><output id="out_storage_mwh">${fmt(p.storage_mwh)}</output> MWh</b></label><input id="storage_mwh" type="range" min="0" max="4000" step="50" value="${p.storage_mwh}"></div><button class="btn primary" id="runStorageScreen">Run evidence-bounded screen</button></div>`}
function scenarioScreenHtml(sc){const s=sc.summary;return `<div class="screen-result"><div><span>Duration</span><b>${s.storage_duration_hours==null?'—':fmt(s.storage_duration_hours,2)+' h'}</b></div><div><span>Efficiency-adjusted energy</span><b>${fmt(s.benchmark_deliverable_storage_mwh,1)} MWh</b></div><div><span>Benchmark capex</span><b>$${compact(s.benchmark_storage_capex_usd)}</b></div><div><span>Peak-gap coverage screen</span><b>${s.screening_hours_covering_current_peak_gap==null?'—':fmt(s.screening_hours_covering_current_peak_gap,2)+' h'}</b></div></div><div class="source-foot">Not a dispatch/reliability study · ${esc(sc.meta.warning)}</div>`}

function demand(){const s=sapp(),c=compactBase(),b=baseline(),n=state.neus,cp=state.censusDistricts;const gap=Math.max(0,s.current_peak_demand_mw-s.operating_capacity_mw);const na=n?.national_access||{};const selected=state.selected?.type==='location'?state.selected:null;return `<div class="workspace"><div class="grid bottom-grid">${metric('Current peak demand',fmt(s.current_peak_demand_mw),'MW','SAPP')}${metric('Operating capacity',fmt(s.operating_capacity_mw),'MW','SAPP')}${metric('Peak capacity gap',fmt(gap),'MW','Arithmetic: peak minus operating capacity')}${metric('NEUS grid connection',na.grid_connection_pct!=null?fmt(na.grid_connection_pct,1):'—','%','Households · NEUS 2022/23')}</div><div class="split dashboard-split">${panel('CAPACITY vs DEMAND',chart('capacityDemand','tall'),'SAPP current snapshot')}${panel('LONG-RUN DEMAND CONTEXT',chart('demandProjection','tall'),'Energy Compact / 2021 IRP baseline')}</div><div class="split dashboard-split">${panel('DISTRICT POPULATION — 2022 CENSUS',chart('districtPopulation','tall'),'Statistics Botswana · population is demand context, not electrical load')}${panel('HOUSEHOLD GRID CONNECTION BY DISTRICT',chart('districtAccess','tall'),'Statistics Botswana NEUS 2022/23 · survey estimate')}</div><div class="split dashboard-split">${panel('WORLDPOP SITE POPULATION',`<div class="resource-point"><small>Analysis coordinate</small><b>${selected?`${selected.lat.toFixed(4)}, ${selected.lng.toFixed(4)}`:'Select a map point first'}</b><p>WorldPop provides gridded population around the selected site. GridIQ does not convert this directly into MW.</p><div class="control"><label>Radius <b><output id="out_worldpop_radius">${fmt(state.worldpop?.radius_km||10)}</output> km</b></label><input id="worldpop_radius" type="range" min="2" max="30" step="1" value="${state.worldpop?.radius_km||10}"></div><button class="btn primary" id="loadWorldpop" ${selected?'':'disabled'}>Query WorldPop</button></div>${state.worldpop?`<div class="big-number">${fmt(state.worldpop.total_population||0)}<small> people</small></div><p class="muted">Within ${fmt(state.worldpop.radius_km)} km · ${state.worldpop.year} · ${esc(state.worldpop.meta?.resolution||'')}</p>${callout('Demand-driver only','Population helps allocate where demand may occur; it is not a metered load profile.','good')}`:'<div class="empty">Select a point on the map, then query population around it.</div>'}`,'Live WorldPop API · 1 km')}${panel('RURAL ELECTRIFICATION EVIDENCE',`<div class="fact-list"><div><span>Households grid connected</span><b>${na.households_grid_connected?fmt(na.households_grid_connected):'—'}</b></div><div><span>Households not grid connected</span><b>${na.households_not_grid_connected?fmt(na.households_not_grid_connected):'—'}</b></div><div><span>Rural households citing distance from lines</span><b>${n?fmt(n.reasons_not_connected_by_locality.find(x=>x.locality==='Rural Villages')?.far_from_lines||0):'—'}</b></div><div><span>Rural households owning PV</span><b>${n?fmt(n.renewable_technology_penetration_by_locality.find(x=>x.locality==='Rural Villages')?.pv_households||0):'—'}</b></div></div>${callout('Interpretation','NEUS directly supports the rural-access problem: distance from electricity lines and connection affordability are observed barriers. It still does not provide feeder MW profiles.','good')}`,'Official household survey evidence')}</div><div class="split dashboard-split">${panel('DEMAND MODEL — WHAT IS NOW ENRICHED',`<div class="alert"><b>National MW anchor</b><span>SAPP peak demand and operating capacity.</span></div><div class="alert"><b>District distribution</b><span>2022 Census population + NEUS grid-connection rates.</span></div><div class="alert"><b>Site population</b><span>WorldPop gridded population can be queried around selected locations.</span></div>${callout('Still missing','Time-aligned feeder/substation load and a measured Botswana hourly load shape remain unavailable. GridIQ therefore does not fabricate dispatch.','warn')}`)}${panel('REGIONAL LOAD BENCHMARK',`<div class="alert"><b>South African DEL study</b><span>20-year household metering dataset exists and is retained as a regional benchmark candidate.</span></div><div class="alert"><b>Current use</b><span>Metadata/method only; raw licensed profiles are not redistributed in this ZIP.</span></div>${callout('Why','A licensed benchmark can calibrate shape later, but must remain labelled South African and cannot be called measured Botswana demand.','good')}`)}</div>${panel('DERIVED DISTRICT ACCESS-PRESSURE INDEX',chart('districtPressure','tall')+callout('Derived indicator only','Population × household grid-connection gap is a prioritisation index. It is <b>not</b> a count of unconnected people or households and it is not MW demand.','warn'),'Census 2022 + NEUS 2022/23 · deterministic join')}<div class="source-foot">Census rows loaded: ${cp?.districts?.length||0} · NEUS district access rows: ${n?.grid_connection_by_district?.length||0} · Joined access-context rows: ${state.districtContext?.records?.filter(r=>r.match_method!=='unmatched').length||0}</div></div>`}

function scenarios(){const p=state.scenarioInputs;return `<div class="workspace"><div class="split scenario-layout">${panel('EVIDENCE-BOUNDED SCENARIO',`<div class="controls">${rangeControl('solar_build_mw','Candidate solar nameplate','MW',0,2000,25,p.solar_build_mw,'User input. Not credited as firm capacity.')}${rangeControl('storage_mw','BESS power','MW',0,1000,10,p.storage_mw,'User input.')}${rangeControl('storage_mwh','BESS energy','MWh',0,6000,50,p.storage_mwh,'User input.')}${rangeControl('peak_demand_mw','Peak demand','MW',300,1200,5,p.peak_demand_mw,'Default = SAPP current peak.')}${rangeControl('operating_capacity_mw','Operating capacity','MW',0,1200,5,p.operating_capacity_mw,'Default = SAPP operating capacity.')}${rangeControl('reserve_requirement_mw','Reserve requirement','MW',0,300,1,p.reserve_requirement_mw,'Default = SAPP peak+reserve minus peak.')}
<button class="btn primary" id="runScenario">Run planning screen</button></div>`,'No synthetic hourly series')}${panel('DECISION OUTPUT',state.scenario?scenarioDecisionHtml(state.scenario):`<div class="empty">Run the planning screen. Outputs are limited to what the current evidence can support.</div>`,'Evidence gates shown explicitly')}</div><div class="callout warn"><b>Why the scenario does not calculate “imports avoided” yet</b><p>That number needs a validated time-aligned load profile, renewable production profile, dispatch assumptions and network constraints. Inventing it would look impressive but would violate the evidence rule.</p></div></div>`}
function rangeControl(id,label,unit,min,max,step,value,note){return `<div class="control"><label>${esc(label)} <b><output id="out_${id}">${fmt(value)}</output> ${esc(unit)}</b></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><small>${esc(note)}</small></div>`}
function scenarioDecisionHtml(sc){const s=sc.summary,g=sc.gates;return `<div class="decision-summary"><div class="screen-result"><div><span>Peak gap</span><b>${fmt(s.current_peak_capacity_gap_mw,1)} MW</b></div><div><span>Gap incl. reserve</span><b>${fmt(s.capacity_gap_including_reserve_mw,1)} MW</b></div><div><span>BESS duration</span><b>${s.storage_duration_hours==null?'—':fmt(s.storage_duration_hours,2)+' h'}</b></div><div><span>BESS benchmark capex</span><b>$${compact(s.benchmark_storage_capex_usd)}</b></div></div><div class="gate-list">${gate('BESS size/cost screen',g.can_calculate_bess_duration_and_benchmark_cost)}${gate('Imports avoided',g.can_calculate_imports_avoided)}${gate('Solar energy yield',g.can_calculate_solar_energy_yield)}${gate('Line congestion',g.can_calculate_line_congestion)}${gate('Reliability capacity credit',g.can_calculate_reliability_capacity_credit)}</div>${callout('Interpretation',esc(sc.meta.warning),'warn')}</div>`}
function gate(label,ok){return `<div class="gate ${ok?'yes':'no'}"><span>${ok?'✓':'×'}</span><b>${esc(label)}</b><small>${ok?'supported now':'requires missing data/model'}</small></div>`}

function dataView(){const rows=state.catalog||[];const mf=state.evidenceManifest;return `<div class="workspace">${mf?panel('EVIDENCE MANIFEST',`<div class="screen-result"><div><span>Bundled files hashed</span><b>${fmt(mf.files?.length||0)}</b></div><div><span>Manifest status</span><b>${esc(mf.status||'unknown')}</b></div></div><p class="muted">SHA-256 checksums make bundled snapshots and benchmarks traceable across releases.</p>`):''}${panel('DATASET TRACEABILITY',`<div class="callout good"><b>Selection rule</b><p>Only sources that feed a map layer, baseline, benchmark, validation metric or planned model input are kept. “Listed on the OIC2 page” is not treated as proof of integration.</p></div><div class="table-wrap" style="margin-top:12px"><table class="data-table"><thead><tr><th>Dataset</th><th>Status</th><th>Evidence class</th><th>Relevance</th><th>Used for</th><th>Known limitation</th><th>Source</th></tr></thead><tbody>${rows.map(d=>`<tr><td><b>${esc(d.name)}</b><small class="table-sub">${esc(d.source)}</small></td><td>${statusBadge(d.status)}</td><td>${esc(d.mode)}</td><td class="score">${d.relevance}/10</td><td>${esc((d.used_for||[]).join(' · '))}</td><td>${esc(d.limits)}</td><td>${sourceLink(d.source_url,'source')}</td></tr>`).join('')}</tbody></table></div>`,'OIC2 catalog + authoritative upstream verification')}</div>`}
function statusBadge(s){const live=/integrated|connected/.test(s)&&!/not-ingested/.test(s);return `<span class="badge ${live?'live':'file'}">${esc(s)}</span>`}

function audit(){const a=state.auditReport;if(!a)return `<div class="workspace">${loadingView('Calculating evidence-gated audit…')}</div>`;const s=a.scores,g=a.gates;const count=x=>Object.values(x||{}).filter(Boolean).length+'/'+Object.keys(x||{}).length;return `<div class="workspace"><div class="grid bottom-grid">${metric('UI/application layer',fmt(s.ui_application,1),'/10',`${count(g.ui_application)} evidence gates passed`)}${metric('Open-data governance',fmt(s.open_data_governance,1),'/10',`${count(g.open_data_governance)} evidence gates passed`)}${metric('Benchmark engineering',fmt(s.benchmark_engineering_capability,1),'/10',`${count(g.benchmark_engineering_capability)} benchmark gates passed`)}${metric('Public-data planning product',fmt(s.public_data_planning_product,1),'/10','Public Botswana evidence + labelled benchmarks')}</div><div class="grid bottom-grid audit-secondary">${metric('BPC operational validation',fmt(s.bpc_operational_validation,1),'/10',`${count(g.bpc_operational_validation)} utility-validation gates passed`)}${metric('Whole solution',fmt(s.whole_solution,1),'/10','Includes unavailable BPC operational validation')}</div><div class="split dashboard-split">${panel('WHAT BENCHMARK ENRICHMENT NOW CLOSES',`<div class="alert"><b>OSM → electrical benchmark branches</b><span>Mapped voltage and line length enriched with documented PyPSA standard R/X/current assumptions.</span></div><div class="alert"><b>DC transfer sensitivity</b><span>Single-voltage benchmark power flow with user-defined transfer, thermal screening and approximate I²R losses.</span></div><div class="alert"><b>Spatial demand driver</b><span>WorldPop live population query complements Census and NEUS without being converted into fabricated MW.</span></div>`)}${panel('WHAT STILL BLOCKS AN OPERATIONAL BPC 9.5',`<div class="alert"><b>BPC bus/branch reconciliation</b><span>Need authoritative buses, transformers, conductor/circuit records, switch state and ratings.</span></div><div class="alert"><b>Time-aligned loads/injections</b><span>Needed for actual congestion, storage dispatch, import displacement and OPF.</span></div><div class="alert"><b>Validated AC / N-1 study</b><span>Benchmark DC transfer is not voltage-security or contingency validation.</span></div>`)}</div><div class="split dashboard-split">${panel('AUDIT GATES — UI',auditGateList(g.ui_application))}${panel('AUDIT GATES — DATA',auditGateList(g.open_data_governance))}</div><div class="split dashboard-split">${panel('AUDIT GATES — BENCHMARK ENGINEERING',auditGateList(g.benchmark_engineering_capability),'Planning-model capability')}${panel('AUDIT GATES — BPC VALIDATION',auditGateList(g.bpc_operational_validation),'Authoritative utility evidence')}</div>${panel('AUDIT POSITION',`<p>${esc(a.position)}</p><p><b>Selected datasets:</b> ${a.catalog.selected} · <b>Integrated/connected:</b> ${a.catalog.integrated_or_connected}</p>${callout('No score inflation','A high public-data planning score means the open-data/benchmark planning product passes its own evidence gates. It does <b>not</b> mean the BPC operational grid has been reconstructed.','good')}`,'Strict evidence-gated rubric')}</div>`}
function auditGateList(obj){return `<div class="gate-list">${Object.entries(obj||{}).map(([k,v])=>gate(k.replaceAll('_',' '),v)).join('')}</div>`}

function loadingView(msg){return `<div class="workspace"><div class="panel"><div class="panel-body loading"><div><div class="spinner"></div>${esc(msg)}</div></div></div></div>`}
const views={overview,network,generation,storage,demand,scenarios,data:dataView,audit};

function render(){const view=views[state.view]?state.view:'overview';state.view=view;$$('.navbtn').forEach(b=>b.classList.toggle('active',b.dataset.view===view));const title=NAV.find(x=>x[0]===view)?.[1]||'GridIQ';$('#pageTitle').textContent=title;$('#workspace').innerHTML=views[view]();bindView();persistState();requestAnimationFrame(mountVisuals)}
function mountVisuals(){if($('#energyMap')){selectionCb=openSelection;if(FIXTURE_MODE){showMapFallback('Browser regression fixture mode · external map/network calls intentionally disabled.')}else if(window.L){ensureMap();if(state.osm.payload){renderPowerData(state.osm.payload,{fit:false});setMapLayer('topology',state.topologyVisible);if(state.engineering.result?.supported&&state.benchmarkVisible)renderBenchmarkFlows(state.engineering.result);updateMapStatus()}else loadOsm(false)}else showMapFallback('Loading OpenStreetMap map engine…')}
  const b=baseline();if(!b)return;const qs=b.quarterly||[],x=q1(),s=sapp(),g=gridBase(),c=compactBase();
  if($('#overviewTrend'))lineChart('overviewTrend',qs.map(r=>r.period),[{label:'Generation MWh',data:qs.map(r=>r.generation_mwh),color:colors.green},{label:'Imports MWh',data:qs.map(r=>r.imports_mwh),color:colors.amber}]);
  if($('#overviewMix'))doughnutChart('overviewMix',['Coal','Solar','Diesel'],[x.generation_mix_pct.coal,x.generation_mix_pct.solar,x.generation_mix_pct.diesel]);
  if($('#voltageKm'))barChart('voltageKm',['400 kV','220 kV','132 kV'],[{label:'Official network km',data:[g.transmission_km_by_voltage['400_kv'],g.transmission_km_by_voltage['220_kv'],g.transmission_km_by_voltage['132_kv']],color:colors.cyan}],{horizontal:true});
  if($('#generationMix'))doughnutChart('generationMix',['Coal','Solar','Diesel'],[x.generation_mix_pct.coal,x.generation_mix_pct.solar,x.generation_mix_pct.diesel]);
  if($('#generationTrend'))lineChart('generationTrend',qs.map(r=>r.period),[{label:'Generation MWh',data:qs.map(r=>r.generation_mwh),color:colors.green},{label:'Imports MWh',data:qs.map(r=>r.imports_mwh),color:colors.amber}]);
  if($('#nasaChart')&&state.nasa?.rows?.length)lineChart('nasaChart',state.nasa.rows.map(r=>r.date.slice(4)),[{label:'Solar kWh/m²/day',data:state.nasa.rows.map(r=>r.ghi),color:colors.amber},{label:'Wind m/s',data:state.nasa.rows.map(r=>r.wind_ms),color:colors.cyan}],{beginAtZero:false});
  if($('#storageCost'))barChart('storageCost',['2010','2024'],[{label:'Global installed cost USD/kWh',data:[2571,state.benchmarks?.utility_scale_bess_2024?.global_total_installed_cost_usd_per_kwh||192],color:colors.violet}]);
  if($('#capacityDemand'))barChart('capacityDemand',['Operating capacity','Peak demand','Peak + reserves'],[{label:'MW',data:[s.operating_capacity_mw,s.current_peak_demand_mw,s.peak_plus_reserves_mw],color:colors.cyan}]);
  if($('#demandProjection'))lineChart('demandProjection',['2020','2040'],[{label:'Electricity demand TWh',data:[c.demand_twh_2020,c.demand_twh_2040_projection],color:colors.violet}],{points:true,beginAtZero:false});
  if($('#districtPopulation')&&state.censusDistricts?.districts?.length){const rows=[...state.censusDistricts.districts].sort((a,b)=>b.population-a.population).slice(0,12);barChart('districtPopulation',rows.map(r=>r.district),[{label:'Population',data:rows.map(r=>r.population),color:colors.cyan}],{horizontal:true});}
  if($('#districtAccess')&&state.neus?.grid_connection_by_district?.length){const rows=[...state.neus.grid_connection_by_district].sort((a,b)=>a.connected_pct-b.connected_pct).slice(0,12);barChart('districtAccess',rows.map(r=>r.district),[{label:'Grid-connected households %',data:rows.map(r=>r.connected_pct),color:colors.green}],{horizontal:true});}
  if($('#districtPressure')&&state.districtContext?.records?.length){const rows=[...state.districtContext.records].filter(r=>r.population_weighted_access_gap_index!=null).sort((a,b)=>b.population_weighted_access_gap_index-a.population_weighted_access_gap_index).slice(0,12);barChart('districtPressure',rows.map(r=>r.census_district),[{label:'Population-weighted access-gap index',data:rows.map(r=>r.population_weighted_access_gap_index),color:colors.amber}],{horizontal:true});}
  $$('[data-chart-wait]').forEach(e=>{if(window.Chart)e.style.display='none'});
}

async function loadOsm(force=false){state.osm.status='loading';updateMapStatus();try{const x=await api(`/api/osm/power${force?'?refresh=true':''}`);state.osm={status:x.meta.cache==='stale'?'stale cache':'loaded',payload:x};renderPowerData(x,{fit:true});setMapLayer('topology',state.topologyVisible);try{state.engineering.enriched=await api(`/api/engineering/enriched-network?case=${state.engineering.case}`)}catch{}if(state.engineering.result?.supported&&state.benchmarkVisible)renderBenchmarkFlows(state.engineering.result);updateMapStatus();const t=$('#topologyStats');if(t)t.innerHTML=topologyStatsHtml(x);toast(`OSM: ${fmt(x.meta.evidence_summary?.line_features||0)} line features · ${fmt(x.meta.evidence_summary?.mapped_line_length_km||0,1)} mapped km`)}catch(e){state.osm.status='live overlay unavailable';updateMapStatus();showMapFallback(e.message);toast(e.message)}}
function updateMapStatus(){const s=$('#mapSourceState');if(s)s.textContent=`OSM · ${state.osm.status}`}

function bindView(){$$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('.map-chip[data-layer]').forEach(b=>b.onclick=()=>{const name=b.dataset.layer;b.classList.toggle('active');const on=b.classList.contains('active');if(name==='topology'){state.topologyVisible=on;persistState()}if(name==='benchmark'){state.benchmarkVisible=on;persistState()}setMapLayer(name,on)});$('#refreshOsm')?.addEventListener('click',()=>loadOsm(true));$('#loadNasa')?.addEventListener('click',loadNasa);$('#loadWorldpop')?.addEventListener('click',loadWorldpop);$('#runEngineering')?.addEventListener('click',runEngineering);$('#useSelectedSink')?.addEventListener('click',()=>{if(state.selected?.type==='location'){state.engineering.sink_lat=state.selected.lat;state.engineering.sink_lon=state.selected.lng;persistState();render()}else toast('Select a map point first')});$('#runScenario')?.addEventListener('click',runScenario);$('#runStorageScreen')?.addEventListener('click',runScenario);$$('.control input').forEach(i=>{i.oninput=()=>{if(i.id==='eng_transfer'){state.engineering.transfer_mw=Number(i.value)}else if(i.id==='worldpop_radius'){const o=$('#out_worldpop_radius');if(o)o.textContent=fmt(i.value);return}else if(i.id in state.scenarioInputs)state.scenarioInputs[i.id]=Number(i.value);const o=$(`#out_${i.id}`);if(o)o.textContent=fmt(i.value);persistState()}});$('#eng_voltage')?.addEventListener('change',e=>{state.engineering.voltage_kv=Number(e.target.value);persistState()});$('#eng_case')?.addEventListener('change',e=>{state.engineering.case=e.target.value;persistState()});['eng_source_lat','eng_source_lon','eng_sink_lat','eng_sink_lon'].forEach(id=>$('#'+id)?.addEventListener('change',e=>{state.engineering[id.replace('eng_','')]=Number(e.target.value);persistState()}))}
async function loadWorldpop(){const selected=state.selected?.type==='location'?state.selected:null;if(!selected)return toast('Select a map point first');const radius=Number($('#worldpop_radius')?.value||10);try{toast('Querying WorldPop…');state.worldpop=await api(`/api/worldpop/population?lat=${selected.lat}&lon=${selected.lng}&radius_km=${radius}&year=2025`);persistState();render()}catch(e){toast(e.message)}}
async function runEngineering(){if(!state.osm.payload){toast('Load the OSM network first');await loadOsm(false);if(!state.osm.payload)return}for(const id of ['source_lat','source_lon','sink_lat','sink_lon']){const el=$('#eng_'+id);if(el)state.engineering[id]=Number(el.value)}state.engineering.transfer_mw=Number($('#eng_transfer')?.value||state.engineering.transfer_mw);state.engineering.voltage_kv=Number($('#eng_voltage')?.value||state.engineering.voltage_kv);state.engineering.case=$('#eng_case')?.value||state.engineering.case;try{toast('Running benchmark DC transfer…');state.engineering.result=await api('/api/engineering/transfer',{method:'POST',body:JSON.stringify({voltage_kv:state.engineering.voltage_kv,case:state.engineering.case,transfer_mw:state.engineering.transfer_mw,source_lat:state.engineering.source_lat,source_lon:state.engineering.source_lon,sink_lat:state.engineering.sink_lat,sink_lon:state.engineering.sink_lon})});state.benchmarkVisible=true;persistState();render();if(state.engineering.result.supported)toast('Benchmark transfer solved');else toast(state.engineering.result.reason)}catch(e){toast(e.message)}}
async function loadNasa(){const lat=state.selected?.type==='location'?state.selected.lat:-24.65,lon=state.selected?.type==='location'?state.selected.lng:25.91;try{toast('Loading NASA POWER…');state.nasa=await api(`/api/nasa/power?lat=${lat}&lon=${lon}&days=14`);persistState();render()}catch(e){toast(e.message)}}
async function runScenario(){for(const id of Object.keys(state.scenarioInputs)){const el=$(`#${id}`);if(el)state.scenarioInputs[id]=Number(el.value)}try{state.scenario=await api('/api/scenario',{method:'POST',body:JSON.stringify(state.scenarioInputs)});persistState();render();toast('Evidence-bounded scenario calculated')}catch(e){toast(e.message)}}

function openSelection(obj){state.selected=obj;persistState();const d=$('#drawer');if(!d)return;$('#drawerKicker').textContent=obj.type==='osm'?'OPENSTREETMAP FEATURE':'ANALYSIS POINT';$('#drawerTitle').textContent=obj.name||obj.power||'Selection';if(obj.type==='osm'){const ef=state.engineering.enriched?.features?.find(f=>f.id===obj.feature_id);const bm=ef?.properties?.benchmark;$('#drawerBody').innerHTML=`<div class="kv"><span>Power type</span><b>${esc(obj.power||'—')}</b><span>Voltage tag</span><b>${esc(obj.voltage||'not mapped')}</b><span>Operator</span><b>${esc(obj.operator||'not mapped')}</b><span>Evidence</span><b>OSM mapped public data</b>${bm?.supported?`<span>Derived length</span><b>${fmt(ef.properties.derived_length_km,2)} km</b><span>Benchmark type</span><b>${esc(bm.line_type)}</b><span>Benchmark X</span><b>${fmt(bm.benchmark_x_total_ohm,3)} Ω</b><span>Benchmark secure rating</span><b>${fmt(bm.benchmark_secure_mva,1)} MVA</b>`:''}</div>${callout('Boundary',bm?.supported?'Geometry/voltage are observed; electrical parameters shown below are external benchmark assumptions, not BPC measurements.':'Geometry and tags are evidence. Capacity/loading/impedance/condition are not inferred.','warn')}`}else{$('#drawerBody').innerHTML=`<div class="kv"><span>Latitude</span><b>${obj.lat.toFixed(5)}</b><span>Longitude</span><b>${obj.lng.toFixed(5)}</b></div>${callout('Resource query point','This coordinate persists when you navigate away. Open Generation → NASA POWER to query the selected site.','good')}`}d.classList.add('open');d.setAttribute('aria-hidden','false');$('#backdrop').hidden=false}
function closeDrawer(){const d=$('#drawer');if(!d)return;d.classList.remove('open');d.setAttribute('aria-hidden','true');$('#backdrop').hidden=true}
function go(v){state.view=views[v]?v:'overview';history.replaceState(null,'',`#${state.view}`);persistState();render()}

async function boot(){restoreState();NAV.forEach(([id,label])=>$('#nav').insertAdjacentHTML('beforeend',`<button class="navbtn" data-view="${id}">${label}</button>`));$$('.navbtn').forEach(b=>b.onclick=()=>go(b.dataset.view));$('#drawerClose').onclick=closeDrawer;$('#backdrop').onclick=closeDrawer;$('#dataBtn').onclick=()=>go('data');try{const h=await api('/api/health');$('#healthPill').className='pill ok';$('#healthPill').textContent=`API ${h.version}`}catch{$('#healthPill').className='pill bad';$('#healthPill').textContent='API offline'}
  const [catalog,base,bench,electrical,plants,neus,censusDistricts,districtContext,auditReport,evidenceManifest]=await Promise.allSettled([api('/api/catalog'),api('/api/baseline'),api('/api/storage-benchmarks'),api('/api/engineering/benchmarks'),api('/api/plants/reference'),api('/api/neus'),api('/api/census/districts'),api('/api/demand/district-context'),api('/api/audit'),api('/api/evidence/manifest')]);if(catalog.status==='fulfilled')state.catalog=catalog.value.datasets;if(base.status==='fulfilled')state.baseline=base.value;if(bench.status==='fulfilled')state.benchmarks=bench.value;if(electrical.status==='fulfilled')state.electricalBenchmarks=electrical.value;if(plants.status==='fulfilled')state.plants=plants.value;if(neus.status==='fulfilled')state.neus=neus.value;if(censusDistricts.status==='fulfilled')state.censusDistricts=censusDistricts.value;if(districtContext.status==='fulfilled')state.districtContext=districtContext.value;if(auditReport.status==='fulfilled')state.auditReport=auditReport.value;if(evidenceManifest.status==='fulfilled')state.evidenceManifest=evidenceManifest.value;
  const hview=location.hash.slice(1);if(views[hview])state.view=hview;$('#updatedAt').textContent=`Evidence snapshot · ${new Date().toLocaleDateString()}`;render();window.__GRID_BOOTED=true;clearTimeout(window.__GRID_BOOT_TIMER);ensureVendors().then(()=>{try{mountVisuals()}catch(e){console.warn(e)}})}

boot().catch(e=>{console.error(e);const ws=$('#workspace');if(ws)ws.innerHTML=`<div class="workspace">${panel('FRONTEND BOOT FAILED',callout('Application startup error',esc(e.message||e),'warn'))}</div>`});
